import numpy as np
from scipy.optimize import least_squares
fams={
 'expA':lambda a: np.exp(-a*A),
 'sinA':lambda a: np.sin(a*A),
 'cosA':lambda a: np.cos(a*A),
 'A/(a+A)':lambda a: A/(a+A),
 'Aa/(1+Aa)':lambda a: a*A/(1+a*A),
 'lnA+a':lambda a: np.log(A+a),
 'sqrtA+a':lambda a: np.sqrt(A+a),
 'A^a':lambda a: A**a,
 'expA2':lambda a: np.exp(-a*A**2),
 'tanhA':lambda a: np.tanh(a*A),
 'A*exp(-aA)*...':lambda a: A*np.exp(-a*A),
}
res_all=[]
for n,f in fams.items():
  for tp in [0,1]:
    def rr(p):
      k,a=p
      X=np.column_stack([np.sqrt(t), np.exp(-k*t)*A**3, t**tp*f(a)])
      c=np.linalg.lstsq(X,dA_dt,rcond=None)[0]
      return dA_dt-X@c
    bb=None
    for a0 in [0.2,0.7,1.5,3]:
      try:
        r=least_squares(rr,[0.09,a0])
        e=np.mean(r.fun**2)/np.var(dA_dt)
        if np.isfinite(e) and (bb is None or e<bb[0]): bb=(e,r.x)
      except Exception: pass
    if bb: res_all.append((n,tp,bb))
for x in sorted(res_all,key=lambda x: x[2][0])[:6]: print(x)
